          "name": "actor_name",
          "attribute": "name",
          "of": "e_actor_matrix"
        },
        {
          "name": "top_co_actors",
          "from": "e_co_actor",
          "by": {
            "count": {
              "id": "r_co_act",
              "condition": {
                "and_conditions": [
                  {
                    "left": { "attribute_name": "id", "of": "e_movie" },
                    "operator": "=",
                    {
                      "left": { "attribute_name": "id", "of": "e_movie" },
                      "operator": "=",
                      {
                        "left": { "attribute_name": "title", "of": "e_movie" },
                        "operator": "=",
                        "The Matrix"
                      }
                    }
                  }
                ]
              }
            }
          },
          "order_by": "count",
          "limit": 3
        }
      ]
    }
  ]
}
